struct GreyWidgetIcon {
  const char *name;
  const uint8_t *dots48;
  const uint8_t *dots40;
};
static const GreyWidgetIcon GREY_WIDGET_ICONS[] = {
  {"pollen", grey_wgt_pollen_48, grey_wgt_pollen_40},
  {"visibility", grey_wgt_visibility_48, grey_wgt_visibility_40},
  {"humidity", grey_wgt_humidity_48, grey_wgt_humidity_40},
  {"dewpoint", grey_wgt_dewpoint_48, grey_wgt_dewpoint_40},
  {"aqi", grey_wgt_aqi_48, grey_wgt_aqi_40},
  {"intemp", grey_wgt_intemp_48, grey_wgt_intemp_40},
  {"inhumidity", grey_wgt_inhumidity_48, grey_wgt_inhumidity_40},
  {"heat_stress", grey_wgt_heat_stress_48, grey_wgt_heat_stress_40},
  {"pressure", grey_wgt_pressure_48, grey_wgt_pressure_40},
};

static inline const uint8_t *getGreyWidgetIcon(const char *name, int16_t size)
{
  if (!name || (size != 40 && size != 48)) return nullptr;
  for (const GreyWidgetIcon &e : GREY_WIDGET_ICONS)
  {
    if (strcmp(e.name, name) == 0)
    {
      return (size == 40) ? e.dots40 : e.dots48;
    }
  }
  return nullptr;
}
